// Chuẩn hóa dữ liệu vào theo contracts/internal/chatbot_input.json
const x = $input.first().json;
if (!x.conversation_id) throw new Error('Thiếu conversation_id');
return [{ json: {
  event_id: x.event_id ?? null,
  conversation_id: String(x.conversation_id),
  message_id: x.message_id != null ? String(x.message_id) : '',
  buyer_user_id: x.buyer_user_id != null ? String(x.buyer_user_id) : '',
  message_type: x.message_type || 'TEXT',
  text: String(x.text ?? '').normalize('NFC').trim(),
  product_id: x.product_id != null ? String(x.product_id) : '',
  channel: x.channel || 'tiktok',
  received_at: x.received_at || new Date().toISOString(),
  started_ms: Date.now(),
} }];

// Bỏ dấu, chữ thường, GIỮ NGUYÊN độ dài chuỗi (mỗi ký tự đổi thành đúng 1 ký tự)
const foldChar = (c) => {
  if (c === 'đ') return 'd';
  if (c === 'Đ') return 'D';
  const b = c.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  return (b || c)[0];
};
const fold = (s) => Array.from(String(s ?? '').normalize('NFC')).map(foldChar).join('').toLowerCase();

// '2tr5' -> 2500000, '500k' -> 500000, '1.990.000đ' -> 1990000 (giống nlu_lib.parse_money)
function parseMoney(s) {
  const m = fold(s).match(/(\d+(?:[.,]\d+)*)\s*(trieu|tr|cu|m|nghin|ngan|k|vnd|dong|d)?\s*(\d+|ruoi)?/);
  if (!m) return null;
  const [, num, unit = '', rest = ''] = m;
  if (['trieu', 'tr', 'cu', 'm'].includes(unit)) {
    let v = parseFloat(num.replace(',', '.')) * 1e6;
    if (rest === 'ruoi') v += 5e5;
    else if (/^\d+$/.test(rest)) v += parseFloat('0.' + rest) * 1e6;
    return Math.round(v);
  }
  if (['nghin', 'ngan', 'k'].includes(unit)) return Math.round(parseFloat(num.replace(',', '.')) * 1000);
  const v = parseInt(num.replace(/[.,]/g, ''), 10);
  if (['vnd', 'dong', 'd'].includes(unit) || v >= 10000) return v;
  return v * 1000;
}
const fmtVnd = (v) => String(v).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + 'đ';

const m = $('Chuẩn bị').first().json;
const ctx = $input.first().json;
let nlu = null, nlu_error = null;

if ($env.NLU_URL && m.text) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST', url: $env.NLU_URL.replace(/\/$/, '') + '/analyze',
      body: { text: m.text }, json: true, timeout: 5000,
    });
    nlu = { intent: r.intent, confidence: r.confidence, entities: r.entities || [], source: 'phobert' };
  } catch (e) {
    nlu_error = 'NLU lỗi: ' + e.message;
  }
}

function rules(text) {
  const f = fold(text);
  const has = (re) => re.test(f);
  const ents = [];
  const add = (label, re) => {
    for (const mm of f.matchAll(re)) ents.push({ label, text: text.substr(mm.index, mm[0].length), start: mm.index });
  };
  add('MA_DON', /\b\d{15,20}\b/g);
  add('NGAN_SACH', /\b\d+(?:[.,]\d+)*\s*(?:trieu|tr|cu|k|nghin|ngan|vnd|dong|d)(?:\s*(?:\d+|ruoi)\b)?(?![a-z])/g);
  add('MAU', /\b(trang|den|xanh duong|xanh la|xanh|xam|hong|tim|bac|do|kem|nau|trong suot|vang)\b/g);
  add('LOAI', /\b(tai nghe(?: bluetooth| chup tai)?|cu sac|dau sac|sac nhanh|sac du phong|pin du phong|cap sac|day sac|cap|op lung|op|kinh cuong luc|cuong luc|loa(?: bluetooth)?|dong ho|vong deo tay|chuot|ban phim|dien thoai|sac)\b/g);
  add('HANG', /\b(anker|baseus|ugreen|apple|samsung|xiaomi|sony|jbl|marshall|logitech|soundpeats|spigen|esr|remax|hoco|oppo|vivo|realme)\b/g);
  add('SAN_PHAM', /\b((?:iphone|ip) ?\d{1,2}(?: pro max| pro| plus| promax)?|galaxy [a-z]\d{1,3}|samsung [a-z]\d{1,3}|redmi note \d+|macbook(?: air| pro)?|ipad(?: gen \d+)?)\b/g);
  for (const e of ents) if (e.label === 'NGAN_SACH') e.value = parseMoney(e.text);

  let intent = 'khac';
  if (has(/(bi loi|loi roi|hong roi|da hong|bi hong|bi re|re mot ben|sai mau|giao sai|giao nham|thieu hang|hoan tien|that vong|buc |khieu nai|tray xuoc|bi mop|khong ket noi|khong vao dien|nong ran|hang gia|chua nhan duoc|lam an kieu|gap nhan vien|gap nguoi)/)) intent = 'khieu_nai';
  else if (has(/(bao hanh|doi tra|1 doi 1|tra hang|doi mau|kiem tra hang truoc)/)) intent = 'bao_hanh';
  else if (ents.some((e) => e.label === 'MA_DON') || has(/(don hang|don cua|don (em|minh|e)\b|ma van don|van don|tinh trang don|bao gio (em |minh )?nhan|gui hang chua|shipper|tra don)/)) intent = 'tra_don';
  else if (has(/( vs |so sanh|khac gi|khac nhau|cai nao (tot|hon|dang|ben|xin|hay)|nen (mua|chon|lay) .+ hay |\bvoi\b.+\b(cai nao|con nao|loai nao)\b.*\b(hon|nhat)\b|\bhay\b.+\b(tot hon|hon)\b)/)) intent = 'so_sanh';
  else if (has(/(tu van|nen mua|nen chon|goi y|\btam \d|duoi \d|khoang \d|ngan sach|loai nao|cai nao|dung cho|hop voi|dung duoc cho|mua them|di kem)/)) intent = 'tu_van';
  else if (has(/(gia|bao nhieu|\bbn\b|nhieu tien|\bnhiu\b|con hang|het hang|co mau|thong so|bao gia)/) || has(/\bcon\b.*\b(khong|ko|k|hong|khum)\b/)) intent = 'hoi_gia';
  return { intent, confidence: intent === 'khac' ? 0.5 : 0.8, entities: ents, source: 'quy_tac' };
}

if (!nlu) nlu = rules(m.text);
if (m.message_type === 'PRODUCT_CARD') {
  nlu.intent = 'hoi_gia';
  if (ctx.card_sku) nlu.entities.push({ label: 'SAN_PHAM', text: ctx.card_sku });
}
const named = nlu.entities.some((e) => ['SAN_PHAM', 'LOAI', 'HANG'].includes(e.label));
const lastSku = (ctx.last_skus || [])[0];
const followUp = /(\bcon\b|het hang|bao nhieu|may cai|\bgia\b|mau gi|mau nao|loai nay|cai nay|cai do)/.test(fold(m.text));
if (!named && !ctx.card_sku && lastSku && followUp && ['khac', 'hoi_gia'].includes(nlu.intent)) {
  nlu.intent = 'hoi_gia';
  nlu.confidence = Math.max(nlu.confidence || 0, 0.7);
  nlu.entities.push({ label: 'SAN_PHAM', text: lastSku, from_context: true });
}
return [{ json: { ...nlu, nlu_error, card_sku: ctx.card_sku || null, history: ctx.history || [],
  last_order_id: ctx.last_order_id || null } }];

