    calls.push({ tool: 'tra_san_pham', args: { query: n.card_sku || first('SAN_PHAM') || m.text, color: first('MAU') } });
    break;
  case 'so_sanh': {
    const names = ents('SAN_PHAM').map((e) => e.text);
    if (names.length >= 2) names.slice(0, 3).forEach((q) => calls.push({ tool: 'tra_san_pham', args: { query: q, color: null } }));
    else calls.push({ tool: 'tra_san_pham', args: { query: m.text, color: null } });
    break;
  }
  case 'tu_van': {
    const device = first('SAN_PHAM');
    const wantsAccessory = /(dung cho|dung duoc cho|hop voi|di kem|mua them|phu kien|cho may)/.test(fold(m.text));
