const toolOut = $input.first().json;
const products = (toolOut.results || []).flatMap((r) => r.products || []);
const anchor = products.find((p) => p.stock > 0);
const eligible = ($env.UPSELL_ENABLED || '1') !== '0' && conv.upsell_group === 'offer'
