  `Ý ĐỊNH (mô hình nhận diện): ${n.intent}`,
  history ? `LỊCH SỬ GẦN ĐÂY:\n${history}` : 'LỊCH SỬ GẦN ĐÂY: (chưa có)',
  plan.ask ? `YÊU CẦU RIÊNG: ${ASK[plan.ask]}` : '',
  tool_errors.length ? 'LƯU Ý: tra dữ liệu bị lỗi, xin lỗi khách và hẹn nhân viên trả lời.' : '',
  upsell.length ? 'MỜI MUA KÈM: sau câu trả lời chính, thêm đúng MỘT câu ngắn, nhẹ nhàng gợi ý món trong goi_y_mua_kem (ghi tên và giá), và đưa SKU món đó vào skus.' : '',
  '<<<DU_LIEU',
  JSON.stringify(data),
  'DU_LIEU>>>',
].filter(Boolean).join('\n');

